import com.eviware.soapui.support.XmlHolder
import net.sf.*
import net.sf.json.*
import net.sf.json.groovy.*

//testRunner.testCase.testSteps["auth"].testRequest.response.toString();

def response = testRunner.testCase.testSteps["auth"].testRequest.response.contentAsString

def jsonSlurper = new JsonSlurper().parseText(response)
def codigo = jsonSlurper.access_token.toString()

testRunner.testCase.testSuite.project.setPropertyValue('Authorization', 'Barer '+codigo)

import com.eviware.soapui.support.XmlHolder
import net.sf.*
import net.sf.json.*
import net.sf.json.groovy.*

//testRunner.testCase.testSteps["auth"].testRequest.response.toString();

def response = testRunner.testCase.testSteps["auth"].testRequest.response.contentAsString

def jsonSlurper = new JsonSlurper().parseText(response)
def codigo = jsonSlurper.access_token.toString()

testRunner.testCase.testSuite.project.setPropertyValue('Authorization',"Beare " + codigo)

import java.util.Random;
import Labels.GeneratorNum;

def longitud= 1;
//Llamatodo dle metodo y clase 
def amtRandom = Labels.GeneratorNum.AMT(longitud);
context.generatorAMT = amtRandom;

/***********SCRIPT RECEPTOR******************/
import imports.Cellxlsx;
import imports.Index;
import java.util.Random;

def excelFilePath = "C:\\Import.xlsx" //Ruta absoluta

/*****Lectura del excel*******/
//Num Hoja
def ReceptorIBPs = Index.readExcelData(excelFilePath, 0);

/*********Instancia Random*************/
def randomIBPs = new Random().nextInt(ReceptorIBPs.size()); //Define las filas dentro de la hoja

//log.info ReceptorIBPs;

context.ListIBPs = ReceptorIBPs;
//log.info (context.ListIBPs [0].id.substring(0,1));

//Variable para contextualizar Lista random
context.ListRandom = randomIBPs;
//log.info(context.ListRandom);

con:configuration.scriptText:
import com.eviware.soapui.support.XmlHolder
import net.sf.*
import net.sf.json.*
import net.sf.json.groovy.*

//Llamar el valor de Transaction_ID
def transaction_id = context.expand('${API-CRE-01-Iniciacion#Response#$.transaction_id}')

def get = new URL("https://pruebas.sypago.net:8086/api/v1/transaction/" + transaction_id).openConnection();

get.setRequestProperty("Authorization", context.expand('${#Project#Authorization}'))

def response = get.getInputStream().getText()

def jsonSlurper = new JsonSlurper().parseText(response)

def TxSts = jsonSlurper.status
assert TxSts == "RJCT"

def Rsn = jsonSlurper.rejected_code
assert Rsn == "MD21"

